<?php require '../config/database.php'; require '../includes/functions.php'; require_admin(); if($_SERVER['REQUEST_METHOD']==='POST'){ $q=$pdo->prepare("INSERT INTO opportunities(title,organization,category,description,location,deadline,application_url,status) VALUES(?,?,?,?,?,?,?,'published')"); $q->execute([trim($_POST['title']),trim($_POST['organization']),trim($_POST['category']),trim($_POST['description']),trim($_POST['location']),$_POST['deadline']?:null,trim($_POST['application_url'])]); } $rows=$pdo->query("SELECT * FROM opportunities ORDER BY created_at DESC")->fetchAll(); site_header('Manage Opportunities'); ?>
<div class="admin-wrap"><h1>Manage Opportunities</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="bookings.php">Bookings</a><a href="messages.php">Messages</a><a href="products.php">Products</a><a href="opportunities.php">Opportunities</a><a href="logout.php">Logout</a></nav><form class="form-card" method="post"><h2>Add opportunity</h2><div class="form-grid"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Organization</label><input name="organization" required></div><div class="field"><label>Category</label><select name="category"><option>Job</option><option>Internship</option><option>Scholarship</option><option>Training</option><option>Volunteering</option></select></div><div class="field"><label>Location</label><input name="location"></div><div class="field"><label>Deadline</label><input type="date" name="deadline"></div><div class="field"><label>Application URL</label><input type="url" name="application_url"></div><div class="field full"><label>Description</label><textarea name="description" required></textarea></div></div><button class="btn">Publish opportunity</button></form><h2>Published opportunities</h2><div class="table-wrap"><table><tr><th>Title</th><th>Organization</th><th>Category</th><th>Deadline</th></tr><?php foreach($rows as $r): ?><tr><td><?=e($r['title'])?></td><td><?=e($r['organization'])?></td><td><?=e($r['category'])?></td><td><?=e($r['deadline'])?></td></tr><?php endforeach; ?></table></div></div><?php site_footer(); ?>